effect.shader:
float gmHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void main(){
vec2 uv=acScreenNorm,g=uv*max(facets,1.0),id=floor(g),f=fract(g);
float tri=step(1.0,f.x+f.y); id+=tri; float seed=gmHash(id);
float a=seed*6.2831853+tri*1.5707963; vec2 n=vec2(cos(a),sin(a));
float faceDepth=(0.35+0.65*seed)*depth, off=refraction*faceDepth;
vec2 qr=clamp(uv+n*off*(1.0+dispersion*0.35),0.0,1.0);
vec2 qg=clamp(uv+n*off,0.0,1.0);
vec2 qb=clamp(uv+n*off*(1.0-dispersion*0.35),0.0,1.0);
vec4 sr=texture2DCv(inputImg.texture,qr),sg=texture2DCv(inputImg.texture,qg),sb=texture2DCv(inputImg.texture,qb);
vec3 col=vec3(sr.r,sg.g,sb.b);
float edge=min(min(f.x,f.y),abs(1.0-f.x-f.y));
float shine=exp(-abs(edge)*max(facets,1.0)*2.2)*sparkle;
col=col*(0.72+0.36*abs(n.y))+shine;
vec4 src=texture2DCv(inputImg.texture,uv);
gl_FragColor=vec4(mix(src.rgb,col,mixAmount),src.a);
}
